import React from 'react'
import { CartProvider, useCart } from 'react-use-cart'
import AllCom from '../Components/AllCom';
import Footer from '../Components/Footer';

function Cart () {

    const {items,updateItemQuantity,removeItem,totalItems,totalUniqueItems,cartTotal,emptyCart,isEmpty}=useCart();
if(isEmpty){
return(
  <div >
          
         
          <h2 className="cl-cart01__empty-title">Your cart is empty</h2>
          <p className="cl-cart01__empty-text">
         
          </p>
          <a   className="cl-cart01__button" href="/product" >
            Continue Shopping
          </a>
        </div>
)
}

return(


<div>
  <main className="cl-cart01-demo">
  <section className="cl-cart01" aria-labelledby="cl-cart01-title">
    <header className="cl-cart01__head">
      <div>
        <p className="cl-cart01__eyebrow"></p>
        <h1 className="cl-cart01__title" id="cl-cart01-title">
          Shopping cart{" "}
           <button
                  className="cl-cart01__remove"
                  type="button"
                  onClick={()=>emptyCart()}
                  data-remove=""
                  aria-label="Remove Aria Wireless Headphones"
                >
                  <svg
                    viewBox="0 0 20 20"
                    width={18}
                    height={18}
                    aria-hidden="true"
                  >
                    <path
                      d="M4 6h12M8 6V4h4v2m-6 0 .7 10h6.6L14 6"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="1.6"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                </button>

          <span className="cl-cart01__count" data-count="" >
           {totalUniqueItems}
          </span>
        </h1>
      </div>
      <a className="cl-cart01__back" href="/product">
        <svg viewBox="0 0 20 20" width={16} height={16} aria-hidden="true">
          <path
            d="M12.5 4.5 7 10l5.5 5.5"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.8"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
        Continue shopping
      </a>
    </header>
    <div className="cl-cart01__layout">
      <div className="cl-cart01__main">
        <table className="cl-cart01__table" data-table="">
          <caption className="cl-cart01__sr">Items in your cart</caption>
          <thead>
            <tr>
              <th scope="col">Product</th>
              <th scope="col">Price</th>
              <th scope="col">Quantity</th>
              <th scope="col">Total</th>
              <th scope="col">
                <span className="cl-cart01__sr">{removeItem}</span>
              </th>
            </tr>
          </thead>

{items.map((item)=>{return(   <tbody data-lines="">
            <tr
              className="cl-cart01__line"
              data-line=""
              data-price={189}
              data-name="Aria Wireless Headphones"
            >
              <td className="cl-cart01__product">
                <img
                  className="cl-cart01__img"
                  src={item.images}
                  width={88}
                  height={88}
                  alt="Mustard over-ear headphones on a yellow background"
                />
                <div>
                  <a className="cl-cart01__name" href="#">
                    {item.title}
                  </a>
                  <p className="cl-cart01__variant">{item.category}</p>
                  <p className="cl-cart01__stock">
                    {item.stock} · ships in 1–2 days
                  </p>
                </div>
              </td>
              <td className="cl-cart01__price" data-label="Price">
               {item.price}
              </td>
              <td data-label="Quantity">
                <div className="cl-cart01__qty">
                  <button
                    className="cl-cart01__step"
                    type="button"
                    onClick={()=>updateItemQuantity(item.id,item.quantity-1)}
                  
                  >
                    <svg
                      viewBox="0 0 16 16"
                      width={14}
                      height={14}
                      aria-hidden="true"
                    >
                      <path
                        d="M3 8h10"
                        stroke="currentColor"
                        strokeWidth={2}
                        strokeLinecap="round"
                      />
                    </svg>
                  </button>
                 <p> {item.quantity}</p>
                  <button
                    className="cl-cart01__step"
                    type="button"
                     onClick={()=>updateItemQuantity(item.id,item.quantity
                      +1)}
                    data-step={1}
                    aria-label="Increase quantity of Aria Wireless Headphones"
                  >
                    <svg
                      viewBox="0 0 16 16"
                      width={14}
                      height={14}
                      aria-hidden="true"
                    >
                      <path
                        d="M3 8h10M8 3v10"
                        stroke="currentColor"
                        strokeWidth={2}
                        strokeLinecap="round"
                      />
                    </svg>
                  </button>
                </div>
              </td>
              <td
                className="cl-cart01__line-total"
                data-label="Total"
                data-line-total=""
              >
               
               ${ Math.ceil(item.price*item.quantity)}
              </td>
              <td className="cl-cart01__rm-cell">
                <button
                  className="cl-cart01__remove"
                  type="button"
                  onClick={()=>removeItem(item.id)}
                  data-remove=""
                  aria-label="Remove Aria Wireless Headphones"
                >
                  <svg
                    viewBox="0 0 20 20"
                    width={18}
                    height={18}
                    aria-hidden="true"
                  >
                    <path
                      d="M4 6h12M8 6V4h4v2m-6 0 .7 10h6.6L14 6"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="1.6"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                </button>
              </td>
            </tr>
           
          </tbody>
)})}

       



        </table>
      
      </div>
      <aside
        className="cl-cart01__summary"
        aria-labelledby="cl-cart01-summary-title"
      >
        <h2 className="cl-cart01__summary-title" id="cl-cart01-summary-title">
          Order summary
        </h2>
        <dl className="cl-cart01__rows">
          <div className ="cl-cart01__row"><dt>Quantity</dt>
          <dd data-Quantity="">{(totalItems)}</dd>
          </div>
          <div className="cl-cart01__row">
            <dt>Subtotal</dt>
            <dd data-subtotal="">$ {Math.ceil(cartTotal)}</dd>
          </div>
          
          <div
            className="cl-cart01__row cl-cart01__row--discount"
            data-discount-row=""
            hidden=""
          >
            
            <dt>
              Discount <span className="cl-cart01__tag">SAVE10</span>
            </dt>
            <dd data-discount="">−$0.00</dd>
          </div>
          <div className="cl-cart01__row">
            <dt>Shipping</dt>
            <dd data-shipping="">$60</dd>
          </div>
         
          <div className="cl-cart01__row cl-cart01__row--total">
            <dt>Total</dt>
            <dd data-total="">{Math.ceil(cartTotal+60)}</dd>
          </div>
        </dl>
        <form className="cl-cart01__coupon" data-coupon="" noValidate="">
          <label className="cl-cart01__label" htmlFor="cl-cart01-code">
            Promo code
          </label>
          <div className="cl-cart01__coupon-row">
            <input
              className="cl-cart01__input"
              id="cl-cart01-code"
              name="code"
              type="text"
              autoComplete="off"
              autoCapitalize="characters"
              spellCheck="false"
              placeholder="Try SAVE10"
              aria-describedby="cl-cart01-code-msg"
            />
            <button className="cl-cart01__apply" type="submit">
              Apply
            </button>
          </div>
          <p
            className="cl-cart01__code-msg"
            id="cl-cart01-code-msg"
            data-code-msg=""
          />
        </form>
        <a
          className="cl-cart01__button cl-cart01__button--wide"
          href="#"
          data-checkout=""
        >
          Proceed to checkout
        </a>
        <p className="cl-cart01__note">
          <svg viewBox="0 0 16 16" width={14} height={14} aria-hidden="true">
            <path
              d="M4 7V5a4 4 0 0 1 8 0v2m-9 0h10v7H3z"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.4"
              strokeLinejoin="round"
            />
          </svg>
          Demo — no payment is taken.
        </p>
        <p className="cl-cart01__free" data-free="">
          You qualify for free shipping.
        </p>
      </aside>
    </div>
    <p
      className="cl-cart01__sr"
      role="status"
      aria-live="polite"
      data-live=""
    />
  </section>
</main>

</div>

)

}

function AllCart() {
  return (
    <CartProvider>
      <AllCom/>
      <Cart/>
    <Footer/>
    </CartProvider>
  )
}

export default AllCart