import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import { createBrowserRouter,RouterProvider } from 'react-router';
import { AllData } from './Data/AllData';
import AllCart from './Cart/AllCart';
import ScrollToTop from 'react-scroll-to-top';
import Td from './TodaySpcial/Td';
import Allmenu from './Menu/Allmenu';
import Allcontact from './Contact/Allcontact';
import AllProducts from './Products/AllProducts';
import ALLDetails from './Details/ALLDetails';


var route =createBrowserRouter([

{

  path:"/",
  element : <App/>
},

{
  path:"today",
  element : <Td/>
},

{
  path:"menu",
  element : <Allmenu/>
},
{
  path:"contact",
  element : <Allcontact/>

},
{
  path:"product",
  element : <AllProducts/>
},
{
  path:"Details/:id",
  element : <ALLDetails/>
},
{
  path:"cart",
  element : <AllCart/>
},


]);
const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
<AllData>
  
 <ScrollToTop/>
 <RouterProvider router={route}/>

</AllData>
 
);

