import React, { useContext, useState } from 'react'
import AllCom from './../Components/AllCom';
import Footer from './../Components/Footer';
import { CartProvider, useCart } from 'react-use-cart';
import { apiValue } from '../Data/AllData';
import { getValue } from '@testing-library/user-event/dist/utils';
import { Link } from 'react-router';


function    Order (){
  const {addItem}= useCart();
 const data = useContext(apiValue);
 const [search,setSearch] = useState("show All");
const   getValue  =(event)=>{
setSearch(event.target.innerHTML);

}
return(
<div>
 <div className="tm-main-section light-gray-bg">
   <div className="container" id="main">
      <div className="col-lg-12 tm-section-header-container margin-bottom-30">


 <h2 className="tm-section-header gold-text tm-handwriting-font">
          <img src="img/logo.png" alt="Logo" className="tm-site-logo" /> Our
          Menus :
        </h2>
         <div className="tm-hr-container">
          <hr className="tm-hr" />
        </div>
      </div>
     </div>


<div class="container text-center filter-btn-container">
    <button  onClick={getValue } type="button" class="btn filter-btn active">show All</button>
    <button onClick={getValue}   type="button" class="btn filter-btn">fragrances
</button> 
    <button onClick={getValue}   type="button" class="btn filter-btn">beauty</button>
    <button   onClick={getValue}   type="button" class="btn filter-btn">furniture</button>
      <button   onClick={getValue}   type="button" class="btn filter-btn">groceries</button>
</div>




    <section className="tm-section row">
    {data.map((item)=>{
    
    return search =="show All"?(
       
       <div className="tm-menu-product-content col-lg-9 col-md-9">
          {" "}
<div className="tm-product">
 

    {/* image: according to api file */}
            <img src={item.images[0]} alt="Product" className="img-thumbnail" />
            <div className="tm-product-text">
              <h3 className="tm-product-title">{item.category}</h3>
              <p className="tm-product-description">
            {item.title}
              </p>
             <Link to={`/Details/${item.id}`}  className="brown-btn">
  Details
</Link>
             <button onClick={()=>addItem(item)}  className="abrown-btn">
 add to cart
</button>
            </div>
            <div className="tm-product-price">
              <a href="#" className="tm-product-price-link tm-handwriting-font">
                <span className="tm-product-price-currency"></span>{item.price}$
              </a>
            </div>
          </div>
        </div>
    ):item.category ==search?( <div className="tm-menu-product-content col-lg-9 col-md-9">
          {" "}
<div className="tm-product">
 
    {/* image: according to api file */}
            <img src={item.images[0]} alt="Product" className="img-thumbnail" />
            <div className="tm-product-text">
              <h3 className="tm-product-title">{item.category}</h3>
              <p className="tm-product-description">
              
            {item.title}
              </p>         <Link to={`/Details/${item.id}`}  className="brown-btn">
  Details
</Link>
  <button onClick={()=>addItem(item)}  className="abrown-btn">
 add to cart
</button>
            </div>
            <div className="tm-product-price">
              <a href="#" className="tm-product-price-link tm-handwriting-font">
                <span className="tm-product-price-currency"></span>{item.price}$
              </a>
            </div>
          </div>
        </div>):null
    
    
    
})}
    </section>
   </div>
 </div>

)
}

function AllProducts() {
  return (
    // لازم احطcart provider instead divعشان مكتبه تظهر
    <CartProvider>
<AllCom/>


<Order/>


<Footer/>
    </CartProvider>
  )
}

export default AllProducts