import React, { useContext, useEffect, useState } from 'react'
import { useParams } from 'react-router'
import AllCom from '../Components/AllCom';
import Footer from '../Components/Footer';
import { CartProvider } from 'react-use-cart';
import { apiValue } from '../Data/AllData';

function ALLDetails() {
     const {id}= useParams();
 const data = useContext(apiValue);


  return  (
   
    <CartProvider>
<AllCom/>

{data.map((elemnt)=>{ 
   return   elemnt.id==id?(
<div className="container">
  <div className="row product-card-wrapper">
    {/* قسم الصورة */}
    <div className="col-md-4 text-center">
      <div className="img-container">
        <img
          src={elemnt.images[0]}
          alt="Product Image"
          className="img-responsive center-block"
          style={{ maxHeight: 200, objectFit: "contain" }}
        />
      </div>
    </div>
    {/* قسم التفاصيل والمعلومات */}
    <div className="col-md-8">
      <div className="row">
        <div className="col-xs-6">
          <span
            className="label"
            style={{
              backgroundColor: "#D5C7B5",
              color: "#4A2E18",
              fontSize: 12
            }}
          >
            {elemnt.category}
          </span>
        </div>
        <div
          className="col-xs-6 text-left"
          style={{ color: "#7A5A3A", fontWeight: "bold" }}
        >
        {elemnt.id}
        </div>
      </div>
      <h3 className="product-title">{elemnt.title}</h3>
      <p className="product-desc">
     {elemnt.description}
      </p>
      {/* السعر والخصم */}
      <div className="price-box clearfix">
        <span className="price-text pull-right">$12.99</span>
        <span
          className="label label-danger pull-left"
          style={{ backgroundColor: "#8C4A2F", marginTop: 5 }}
        >
         {elemnt.discountPercentage} discount
        </span>
      </div>
      {/* التقييم والمخزون */}
      <div className="row" style={{ marginBottom: 15 }}>
        <div className="col-xs-6">
          <div className="stat-box">
            <small style={{ color: "#7A5A3A", display: "block" }}>
              {elemnt.rating}
            </small>
            <strong style={{ color: "#C69214" }}>★ 4.8</strong>
          </div>
        </div>
        <div className="col-xs-6">
          <div className="stat-box">
            <small style={{ color: "#7A5A3A", display: "block" }}>
              {elemnt.stock}
            </small>
            <strong style={{ color: "#5C3A21" }}>25 قطعة</strong>
          </div>
        </div>
      </div>
      {/* الوسوم (Tags) */}
      <div style={{ marginBottom: 15 }}>
        <small style={{ color: "#7A5A3A", fontWeight: "bold" }}>Tags:</small>
        <span className="custom-tag">#{elemnt.tags}</span>
        <span className="custom-tag">#{elemnt.tags}</span>
      </div>
      {/* زر التفاصيل */}
      
    <a   className="cl-cart01__button" href="/product" >
            Continue Shopping
          </a>
    </div>
  </div>
</div>
):null
})}

<Footer/>
    </CartProvider>
  )
}

export default ALLDetails