import React, { useState } from 'react';

function Nav({ totalItems }) {
  const [isOpen, setIsOpen] = useState(false);

  const toggleMenu = () => {
    setIsOpen(!isOpen);
  };

  return (
    <div>
      <div className="tm-top-header">
        <div className="container">
          <div className="row">
            <div className="tm-top-header-inner">
              
              <div className="tm-logo-container">
                <img src="img/logo.png" alt="Logo" className="tm-site-logo" />
                <h1 className="tm-site-name tm-handwriting-font">Cafe House</h1>
              </div>

              {/* زر الموبايل */}
              <div className="mobile-menu-icon" onClick={toggleMenu} style={{ cursor: 'pointer' }}>
                <i className={`fa ${isOpen ? 'fa-times' : 'fa-bars'}`} />
              </div>

              {/* تحكم مباشر بالظهور والإخفاء */}
              <nav 
                className={`tm-nav ${isOpen ? 'show-element' : ''}`}
                style={{ display: isOpen ? 'block' : undefined }}
              >
                <ul style={{ display: isOpen ? 'block' : undefined }}>
                  <li>
                    <a href="/" className="active">Home</a>
                  </li>
                  <li>
                    <a href="/today">Today Special</a>
                  </li>
                  <li>
                    <a href="/menu">Menu</a>
                  </li>
                  <li>
                    <a href="/contact">Contact</a>
                  </li>
                  <li>
                    <a href="/product">Product</a>
                  </li>
                  <li>
                    <a href="/cart">
                      <i className="fa-solid fa-bag-shopping">Shopping Cart<br /> {totalItems}</i> 
                     
                    </a>
                  </li>
                </ul>
              </nav>

            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Nav;